- Create article with flexible schema

```python
"""
Content Management System with MongoDB
Best for: Flexible schemas, nested data, rapid development
"""

from pymongo import MongoClient
from bson.objectid import ObjectId
from datetime import datetime
from typing import List, Optional

class ContentManagementSystem:
    """
    MongoDB for CMS

    Why MongoDB?
    - Flexible schema for different content types
    - Embedded documents for related data
    - Rich query language
    - Easy to iterate on schema
    """

    def __init__(self, connection_string: str):
        self.client = MongoClient(connection_string)
        self.db = self.client['cms']
        self.articles = self.db['articles']
        self.users = self.db['users']

        # Create indexes
        self.articles.create_index([("title", "text"), ("content", "text")])
        self.articles.create_index("author_id")
        self.articles.create_index("tags")
        self.articles.create_index("published_at")

    def create_article(self, article_data: dict) -> str:
        """
        Create article with embedded comments and metadata

        Document structure is flexible - different articles
        can have different fields
        """
        article = {
            "title": article_data["title"],
            "slug": self._generate_slug(article_data["title"]),
            "content": article_data["content"],
            "author_id": article_data["author_id"],
            "tags": article_data.get("tags", []),
            "metadata": {
                "word_count": len(article_data["content"].split()),
                "reading_time_minutes": len(article_data["content"].split()) // 200,
                "featured_image": article_data.get("featured_image")
            },
            "comments": [],  # Embedded comments
            "views": 0,
            "likes": 0,
            "status": "draft",
            "created_at": datetime.utcnow(),
            "updated_at": datetime.utcnow()
        }

        # Add optional fields if provided
        if "category" in article_data:
            article["category"] = article_data["category"]

        if "custom_fields" in article_data:
            article["custom_fields"] = article_data["custom_fields"]

        result = self.articles.insert_one(article)
        return str(result.inserted_id)

    def add_comment(self, article_id: str, comment_data: dict) -> bool:
        """
        Add embedded comment to article

        Comments are embedded because:
        - Always accessed with article
        - Limited number per article
        - No need for cross-article queries
        """
        comment = {
            "_id": ObjectId(),
            "author_id": comment_data["author_id"],
            "author_name": comment_data["author_name"],
            "content": comment_data["content"],
            "created_at": datetime.utcnow(),
            "likes": 0,
            "replies": []  # Nested replies
        }

        result = self.articles.update_one(
            {"_id": ObjectId(article_id)},
            {
                "$push": {"comments": comment},
                "$set": {"updated_at": datetime.utcnow()}
            }
        )

        return result.modified_count > 0

    def get_article_with_author(self, article_id: str) -> dict:
        """
        Aggregation pipeline to join with users collection
        """
        pipeline = [
            {"$match": {"_id": ObjectId(article_id)}},
            {
                "$lookup": {
                    "from": "users",
                    "localField": "author_id",
                    "foreignField": "_id",
                    "as": "author"
                }
            },
            {"$unwind": "$author"},
            {
                "$project": {
                    "title": 1,
                    "content": 1,
                    "tags": 1,
                    "views": 1,
                    "comments": 1,
                    "author.name": 1,
                    "author.avatar": 1,
                    "created_at": 1
                }
            }
        ]

        result = list(self.articles.aggregate(pipeline))
        return result[0] if result else None

    def search_articles(self, query: str, filters: dict = None) -> List[dict]:
        """
        Full-text search with filters
        """
        search_query = {
            "$text": {"$search": query}
        }

        if filters:
            if "tags" in filters:
                search_query["tags"] = {"$in": filters["tags"]}
            if "status" in filters:
                search_query["status"] = filters["status"]
            if "date_range" in filters:
                search_query["published_at"] = {
                    "$gte": filters["date_range"]["start"],
                    "$lte": filters["date_range"]["end"]
                }

        return list(self.articles.find(
            search_query,
            {"score": {"$meta": "textScore"}}
        ).sort([("score", {"$meta": "textScore"})]).limit(20))

    def get_trending_articles(self, days: int = 7) -> List[dict]:
        """
        Aggregation for trending articles
        """
        cutoff_date = datetime.utcnow() - timedelta(days=days)

        pipeline = [
            {
                "$match": {
                    "status": "published",
                    "published_at": {"$gte": cutoff_date}
                }
            },
            {
                "$addFields": {
                    "engagement_score": {
                        "$add": [
                            "$views",
                            {"$multiply": ["$likes", 5]},
                            {"$multiply": [{"$size": "$comments"}, 10]}
                        ]
                    }
                }
            },
            {"$sort": {"engagement_score": -1}},
            {"$limit": 10},
            {
                "$project": {
                    "title": 1,
                    "slug": 1,
                    "tags": 1,
                    "views": 1,
                    "likes": 1,
                    "comment_count": {"$size": "$comments"},
                    "engagement_score": 1,
                    "published_at": 1
                }
            }
        ]

        return list(self.articles.aggregate(pipeline))

    def update_article_schema(self):
        """
        Schema migration example - add new field to all documents
        MongoDB allows gradual schema evolution
        """
        # Add new field with default value
        self.articles.update_many(
            {"seo_meta": {"$exists": False}},
            {"$set": {"seo_meta": {"description": "", "keywords": []}}}
        )

    def _generate_slug(self, title: str) -> str:
        import re
        slug = title.lower()
        slug = re.sub(r'[^a-z0-9]+', '-', slug)
        slug = slug.strip('-')
        return slug

# Usage
cms = ContentManagementSystem("mongodb://localhost:27017")

# Create article with flexible schema
article_id = cms.create_article({
    "title": "Introduction to System Design",
    "content": "System design is the process of...",
    "author_id": ObjectId("..."),
    "tags": ["system-design", "architecture"],
    "custom_fields": {  # Flexible - different articles can have different fields
        "difficulty": "intermediate",
        "estimated_completion": "45 minutes"
    }
})
```
